BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @hasta datetime2(3) = SYSUTCDATETIME();
    DECLARE @desde datetime2(3) = (SELECT ultima_marca FROM ctl.marcas_agua WHERE tabla = 'pedidos');

    WITH lote AS (
        SELECT *, ROW_NUMBER() OVER (PARTITION BY pedido_id ORDER BY modificado_en DESC) AS rn
        FROM raw.pedidos
        WHERE modificado_en > @desde AND modificado_en <= @hasta
    )
    MERGE dw.pedidos AS d
    USING (SELECT * FROM lote WHERE rn = 1) AS o
       ON d.pedido_id = o.pedido_id
    WHEN MATCHED AND (d.estado <> o.estado OR d.total <> o.total) THEN
        UPDATE SET d.estado = o.estado, d.total = o.total, d.actualizado_en = @hasta
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (pedido_id, cliente_id, total, estado, actualizado_en)
        VALUES (o.pedido_id, o.cliente_id, o.total, o.estado, @hasta);

    UPDATE ctl.marcas_agua SET ultima_marca = @hasta WHERE tabla = 'pedidos';

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

