import time
import requests

ESPERADAS = {"id", "email", "plan", "creado_en"}


def leer_todo(url, token):
    filas, pagina = [], url
    while pagina:
        for intento in range(4):
            r = requests.get(pagina, headers={"Authorization": f"Bearer {token}"}, timeout=30)
            if r.status_code in (429, 503):
                time.sleep(2 ** intento)   # espera 1, 2, 4, 8 segundos
                continue
            r.raise_for_status()
            break
        datos = r.json()
        filas.extend(datos["results"])
        pagina = datos.get("next")
    return filas


def revisar_esquema(filas):
    recibidas = set().union(*(f.keys() for f in filas)) if filas else set()
    nuevas, faltan = recibidas - ESPERADAS, ESPERADAS - recibidas
    if nuevas or faltan:
        print(f"AVISO esquema: nuevas={sorted(nuevas)} faltan={sorted(faltan)}")

