CREATE OR ALTER PROCEDURE dw.cargar_ventas @fecha date
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRANSACTION;

    DELETE FROM dw.fct_ventas_dia WHERE fecha = @fecha;

    INSERT INTO dw.fct_ventas_dia (fecha, sucursal_id, ventas, pedidos)
    SELECT @fecha, sucursal_id, SUM(total), COUNT(*)
    FROM stg.pedidos
    WHERE fecha_pedido = @fecha
    GROUP BY sucursal_id;

    COMMIT TRANSACTION;
END;

