from airflow.sdk import task
from airflow.providers.microsoft.mssql.hooks.mssql import MsSqlHook


@task(task_id="ingerir_pagos")
def ingerir_pagos(data_interval_start=None, data_interval_end=None) -> int:
    hook = MsSqlHook(mssql_conn_id="almacen_mssql")
    hook.run(
        "EXEC raw.cargar_pagos @desde = %s, @hasta = %s",
        parameters=(data_interval_start, data_interval_end),
    )
    filas = hook.get_first(
        "SELECT COUNT(*) FROM raw.pagos WHERE _cargado_en >= %s AND _cargado_en < %s",
        parameters=(data_interval_start, data_interval_end),
    )[0]
    if filas == 0:
        raise ValueError("La pasarela no entregó pagos en el intervalo")
    return filas
